type failedResult struct {
	FailedMailboxes []mailboxRecord `json:"failedMailboxes"`
	FailedCount     int             `json:"failedCount"`
}

func newNovelMailboxesFailedCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "failed",
		Short: "Mailboxes that failed or stalled during creation, ready to retry",
		Long: strings.Trim(`
List mailboxes whose status is not ACTIVE - failed, pending, or stalled
creations - across every domain, so you can retry them before they show up as
missing send volume.

Do NOT use this for warmed-idle mailboxes; use 'mailboxes idle'. For every
mailbox regardless of state, use 'mailboxes list'.
`, "\n"),
		Example:     "  zapmail-pp-cli mailboxes failed --json",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRunOK(flags) {
				return nil
			}
			all, _, err := fetchAllMailboxes(cmd, flags)
			if err != nil {
				return err
			}
			failed := []mailboxRecord{}
			for _, m := range all {
				if !strings.EqualFold(strings.TrimSpace(m.Status), "ACTIVE") {
					failed = append(failed, m)
				}
			}
			fmt.Fprintf(cmd.ErrOrStderr(), "failed: %d mailboxes not in ACTIVE status\n", len(failed))
			return printJSONFiltered(cmd.OutOrStdout(), failedResult{FailedMailboxes: failed, FailedCount: len(failed)}, flags)
		},
	}
	return cmd
}
